INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine bestimmte Adresse immer an alle Geräte sendet?', 2, '[{"text": "Ja", "correct": true, "because": "Broadcast macht das"}, {"text": "Nein", "correct": false, "because": "Broadcast ist speziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wird genutzt, um das eigene Gerät zu testen?', 3, '[{"text": "127.0.0.1", "correct": true, "because": "Loopback-Adresse"}, {"text": "255.255.255.255", "correct": false, "because": "Broadcast"}, {"text": "192.168.0.1", "correct": false, "because": "Private Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen haben spezielle Funktionen in Netzwerken?', 5, '[{"text": "Loopback", "correct": true, "because": "Lokale Tests"}, {"text": "Broadcast", "correct": true, "because": "An alle senden"}, {"text": "Private Adressen", "correct": true, "because": "Interne Nutzung"}, {"text": "Farbcodierte Adressen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0 ist privat. b) 255.255.255.255 ist für Loopback.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "255.255.255.255 ist Broadcast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk einrichte?', 4, '[{"text": "Private Adressen", "correct": false, "because": "Für interne Nutzung"}, {"text": "Loopback", "correct": false, "because": "Für Tests wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 127.0.0.1 nur für Server ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für jedes Gerät"}, {"text": "Ja", "correct": false, "because": "Allgemeine Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist für Multicast in IPv4 reserviert?', 3, '[{"text": "224.0.0.0", "correct": true, "because": "Beginn des Multicast-Bereichs"}, {"text": "10.0.0.0", "correct": false, "because": "Private Adresse"}, {"text": "127.0.0.1", "correct": false, "because": "Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche sind für private Netzwerke reserviert?', 5, '[{"text": "10.0.0.0 - 10.255.255.255", "correct": true, "because": "Klasse A privat"}, {"text": "172.16.0.0 - 172.31.255.255", "correct": true, "because": "Klasse B privat"}, {"text": "192.168.0.0 - 192.168.255.255", "correct": true, "because": "Klasse C privat"}, {"text": "200.0.0.0 - 200.255.255.255", "correct": false, "because": "Öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) ::1 die IPv6-Loopback ist und b) 255.255.255.255 privat ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "255.255.255.255 ist Broadcast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um spezielle Adressen zu nutzen?', 4, '[{"text": "Netzwerkkonfiguration", "correct": false, "because": "Definiert Nutzung"}, {"text": "Subnetzmaske", "correct": false, "because": "Trennt Bereiche"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 0.0.0.0 eine gültige Host-Adresse?', 2, '[{"text": "Nein", "correct": true, "because": "Reserviert für Default"}, {"text": "Ja", "correct": false, "because": "Spezielle Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen dienen der lokalen Kommunikation?', 4, '[{"text": "127.0.0.0/8", "correct": true, "because": "Loopback-Bereich"}, {"text": "169.254.0.0/16", "correct": true, "because": "Link-Local"}, {"text": "200.0.0.0/8", "correct": false, "because": "Öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass private Adressen im Internet routbar sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur intern nutzbar"}, {"text": "Ja", "correct": false, "because": "NAT erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Loopback-Adresse?', 3, '[{"text": "Lokale Tests", "correct": true, "because": "Prüft eigenes Gerät"}, {"text": "Datenübertragung", "correct": false, "because": "Kein Ziel"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 10.0.0.0 ist privat. b) ::1 ist für Broadcast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "::1 ist Loopback"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt 255.255.255.255?', 4, '[{"text": "Broadcast", "correct": true, "because": "Sendet an alle"}, {"text": "Loopback", "correct": false, "because": "127.0.0.1"}, {"text": "Private Adresse", "correct": false, "because": "Öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 169.254.0.0 für manuelle Zuweisung ist?', 2, '[{"text": "Nein", "correct": true, "because": "Automatische Link-Local"}, {"text": "Ja", "correct": false, "because": "APIPA"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen spezielle Adressen nützlich?', 5, '[{"text": "Lokale Tests", "correct": true, "because": "Loopback"}, {"text": "Interne Netzwerke", "correct": true, "because": "Private Adressen"}, {"text": "Broadcast-Kommunikation", "correct": true, "because": "An alle"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ::1 für IPv4?', 3, '[{"text": "Nein", "correct": true, "because": "IPv6-Loopback"}, {"text": "Ja", "correct": false, "because": "127.0.0.1 für IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer speziellen Adresse?', 4, '[{"text": "Ping 127.0.0.1 zum Testen", "correct": true, "because": "Loopback-Nutzung"}, {"text": "Webseitenhosting", "correct": false, "because": "Öffentliche Adresse"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}]');
